/* Relaywise product page. Tokens and rationale live in DESIGN.md. */

:root {
  --bg: oklch(0.975 0.006 165);
  --surface: oklch(1 0 0);
  --ink: oklch(0.24 0.03 200);
  --muted: oklch(0.46 0.02 200);
  --accent: oklch(0.49 0.12 160);
  --accent-press: oklch(0.42 0.11 160);
  --chip: oklch(0.95 0.02 165);
  --beta: oklch(0.94 0.05 85);
  --beta-ink: oklch(0.40 0.08 70);
  --rule: oklch(0.90 0.01 180);     /* decorative card edges */
  --line: oklch(0.62 0.03 180);     /* route line, 3.6:1 on surface */
  --foot-muted: oklch(0.82 0.02 190);
  --ring: var(--accent);

  --display: "Bricolage Grotesque", "Segoe UI", system-ui, sans-serif;
  --body: "Atkinson Hyperlegible", system-ui, sans-serif;

  --r-chip: 999px;
  --r-btn: 0.5rem;
  --r-card: 0.75rem;
  --r-panel: 1rem;
  --ease: cubic-bezier(0.22, 1, 0.36, 1); /* ease-out quint */

  color-scheme: light;
}

*, *::before, *::after { box-sizing: border-box; }

html { scroll-behavior: smooth; }
@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 1.0625rem/1.6 var(--body);
  -webkit-font-smoothing: antialiased;
}

::selection { background: var(--accent); color: var(--surface); }

h1, h2, h3 {
  font-family: var(--display);
  line-height: 1.1;
  margin: 0;
  text-wrap: balance;
}
p { margin: 0; text-wrap: pretty; }
ul, ol { margin: 0; padding: 0; list-style: none; }

a { color: inherit; text-underline-offset: 0.2em; }

:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 3px;
  border-radius: 2px;
}

.vh {
  position: absolute !important;
  width: 1px; height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.skip {
  position: absolute;
  left: 1rem; top: -4rem;
  padding: 0.75rem 1rem;
  background: var(--ink);
  color: var(--surface);
  border-radius: var(--r-btn);
  z-index: 10;
}
.skip:focus { top: 1rem; }

.wrap {
  width: min(100% - 2.5rem, 72rem);
  margin-inline: auto;
}

/* ---------- Buttons & links ---------- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 3rem;
  padding: 0.75rem 1.375rem;
  border-radius: var(--r-btn);
  border: 2px solid var(--accent);
  font: 700 1rem/1.2 var(--body);
  text-decoration: none;
  text-align: center;
  touch-action: manipulation;
  transition: background-color 180ms var(--ease), color 180ms var(--ease), border-color 180ms var(--ease);
}
.btn-primary { background: var(--accent); color: var(--surface); }
.btn-secondary { background: var(--surface); color: var(--accent); }
.btn-small { min-height: 2.75rem; padding: 0.5rem 1rem; }

@media (hover: hover) {
  .btn-primary:hover { background: var(--accent-press); border-color: var(--accent-press); }
  .btn-secondary:hover { background: var(--chip); }
  .text-link:hover, .card-link:hover, .site-header nav a:hover { text-decoration-thickness: 2px; }
}
.btn-primary:active { background: var(--accent-press); border-color: var(--accent-press); transition-duration: 60ms; }
.btn-secondary:active { background: var(--chip); transition-duration: 60ms; }

.text-link, .card-link {
  font-weight: 700;
  color: var(--accent);
  text-decoration: underline;
  text-decoration-thickness: 1px;
}

/* ---------- Header ---------- */

.header-inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 1.5rem;
  padding-block: 1rem;
}
.wordmark {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font: 800 1.375rem/1 var(--display);
  text-decoration: none;
  min-height: 2.75rem;
}
/* The route node, reused as the logo mark */
.wordmark-node {
  width: 0.75rem; height: 0.75rem;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 1rem 0 0 -0.2rem var(--accent);
  margin-right: 0.8rem;
}
.site-header nav { margin-left: auto; }
.site-header nav ul { display: flex; gap: 0.25rem 1.25rem; flex-wrap: wrap; }
.site-header nav a {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  text-decoration: none;
  font-weight: 700;
}

@media (max-width: 34rem) {
  /* Nav wraps to its own row instead of disappearing */
  .site-header nav { order: 3; margin-left: 0; width: 100%; }
  .header-inner > .btn { margin-left: auto; }
}

/* ---------- Hero ---------- */

.hero { padding-block: clamp(2.5rem, 6vw, 6rem) clamp(4rem, 8vw, 7rem); }
.hero-inner {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr);
  gap: clamp(2.5rem, 5vw, 4.5rem);
  align-items: center;
}
.hero h1 {
  font-size: clamp(2.25rem, 1.3rem + 3.6vw, 4.25rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.02;
}
.lede {
  margin-top: 1.5rem;
  font-size: 1.1875rem;
  color: var(--muted);
  max-width: 34rem;
}
.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem 1.75rem;
  margin-top: 2.25rem;
}
.hero-actions .text-link { min-height: 2.75rem; display: inline-flex; align-items: center; }
.fine { margin-top: 1rem; font-size: 0.9375rem; color: var(--muted); }

/* The routing panel: the page's one raised object */
.panel {
  margin: 0;
  background: var(--surface);
  border: 1px solid var(--rule);
  border-radius: var(--r-panel);
  box-shadow: 0 1.5rem 3rem -1.5rem oklch(0.24 0.03 200 / 0.25);
  padding: 0.5rem 1.25rem 1rem;
}
.panel-head {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.25rem 1rem;
  padding-block: 0.75rem;
  border-bottom: 1px solid var(--rule);
  font-weight: 700;
  font-size: 0.9375rem;
}
.panel-status { color: var(--accent); }
.routes .route {
  padding-block: 1.125rem;
}
.routes .route + .route { border-top: 1px solid var(--rule); }

/* ---------- Signature: the route line ---------- */
/* from ──● to. Same shape in the hero, every card, every tier. */

.route {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(1.5rem, 3.5rem) auto;
  align-items: center;
  column-gap: 0.625rem;
}
.route-from { display: grid; min-width: 0; overflow-wrap: anywhere; }
.route-subject { font-weight: 700; }
.route-meta { font-size: 0.875rem; color: var(--muted); }
.route-line {
  position: relative;
  height: 2px;
  background: var(--line);
  transform-origin: left center;
}
.route-line::before,
.route-line::after {
  content: "";
  position: absolute;
  top: 50%;
  border-radius: 50%;
  translate: 0 -50%;
}
.route-line::before { left: -3px; width: 7px; height: 7px; background: var(--line); }
.route-line::after { right: -5px; width: 10px; height: 10px; background: var(--accent); }
.route-line-dashed {
  background: repeating-linear-gradient(90deg, var(--line) 0 4px, transparent 4px 8px);
}
.route-line-dashed::after { background: var(--surface); border: 2px solid var(--accent); }

.route-to {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.3rem 0.75rem 0.3rem 0.3rem;
  border-radius: var(--r-chip);
  background: var(--chip);
  font-weight: 700;
  font-size: 0.9375rem;
  white-space: nowrap;
}
.avatar {
  display: grid;
  place-items: center;
  width: 1.75rem; height: 1.75rem;
  border-radius: 50%;
  background: var(--accent);
  color: var(--surface);
  font-size: 0.75rem;
  letter-spacing: 0.02em;
}

.route-mini { font-size: 0.875rem; }
.route-mini .route-from { color: var(--muted); font-weight: 700; }
.route-mini .route-to { padding: 0.2rem 0.65rem; font-size: 0.875rem; white-space: normal; }

@media (max-width: 26rem) {
  /* Hero rows: destination drops under the subject so nothing squeezes */
  .routes .route { grid-template-columns: minmax(1.5rem, 2.5rem) auto; row-gap: 0.5rem; }
  .routes .route-from { grid-column: 1 / -1; }
  .routes .route-to { justify-self: start; }
}

/* One orchestrated entrance: the hero routes draw in, in order.
   Lines are visible by default; motion only enhances. */
@media (prefers-reduced-motion: no-preference) {
  .routes .route-line { animation: draw 600ms var(--ease) backwards; }
  .routes .route-to { animation: arrive 300ms var(--ease) backwards; }
  .routes .route:nth-child(1) .route-line { animation-delay: 250ms; }
  .routes .route:nth-child(1) .route-to { animation-delay: 750ms; }
  .routes .route:nth-child(2) .route-line { animation-delay: 450ms; }
  .routes .route:nth-child(2) .route-to { animation-delay: 950ms; }
  .routes .route:nth-child(3) .route-line { animation-delay: 650ms; }
  .routes .route:nth-child(3) .route-to { animation-delay: 1150ms; }
}
@keyframes draw { from { transform: scaleX(0); } }
@keyframes arrive { from { opacity: 0; transform: translateX(-0.5rem); } }

/* ---------- Sections ---------- */

.section-head {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
  gap: 1rem 3rem;
  align-items: end;
  margin-bottom: 2.5rem;
}
.section-head h2 {
  font-size: clamp(1.75rem, 1.2rem + 2vw, 2.75rem);
  font-weight: 700;
  letter-spacing: -0.02em;
}
.section-head p { color: var(--muted); max-width: 36rem; }

@media (max-width: 48rem) {
  .hero-inner, .section-head { grid-template-columns: minmax(0, 1fr); }
}

.features { padding-block: clamp(4rem, 8vw, 6.5rem); background: var(--surface); border-block: 1px solid var(--rule); }

.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr));
  gap: 1.25rem;
}
.card {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding: 1.5rem;
  border: 1px solid var(--rule);
  border-radius: var(--r-card);
  background: var(--bg);
}
.card .route-mini { margin-bottom: 0.75rem; }
.card h3 { font-size: 1.3125rem; font-weight: 700; letter-spacing: -0.01em; }
.card > p:not(.route) { color: var(--muted); }
.card-link { margin-top: auto; align-self: flex-start; padding-block: 0.25rem; }

.chips { display: flex; flex-wrap: wrap; gap: 0.5rem; }
.chip {
  display: inline-block;
  padding: 0.2rem 0.65rem;
  border-radius: var(--r-chip);
