  --accent-press: oklch(0.42 0.11 160);
  --chip: oklch(0.95 0.02 165);
  --beta: oklch(0.94 0.05 85);
  --beta-ink: oklch(0.40 0.08 70);
  --rule: oklch(0.90 0.01 180);     /* decorative card edges */
  --line: oklch(0.62 0.03 180);     /* route line, 3.6:1 on surface */
  --foot-muted: oklch(0.82 0.02 190);
  --ring: var(--accent);

  --display: "Bricolage Grotesque", "Segoe UI", system-ui, sans-serif;
  --body: "Atkinson Hyperlegible", system-ui, sans-serif;

