}
p { margin: 0; text-wrap: pretty; }
ul, ol { margin: 0; padding: 0; list-style: none; }

a { color: inherit; text-underline-offset: 0.2em; }

:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 3px;
  border-radius: 2px;
}

.vh {
  position: absolute !important;
  width: 1px; height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.skip {
  position: absolute;
  left: 1rem; top: -4rem;
  padding: 0.75rem 1rem;
  background: var(--ink);
  color: var(--surface);
  border-radius: var(--r-btn);
  z-index: 10;
}
.skip:focus { top: 1rem; }

.wrap {
  width: min(100% - 2.5rem, 72rem);
  margin-inline: auto;
}

/* ---------- Buttons & links ---------- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 3rem;
  padding: 0.75rem 1.375rem;
  border-radius: var(--r-btn);
  border: 2px solid var(--accent);
  font: 700 1rem/1.2 var(--body);
  text-decoration: none;
  text-align: center;
  touch-action: manipulation;
  transition: background-color 180ms var(--ease), color 180ms var(--ease), border-color 180ms var(--ease);
}
.btn-primary { background: var(--accent); color: var(--surface); }
.btn-secondary { background: var(--surface); color: var(--accent); }
.btn-small { min-height: 2.75rem; padding: 0.5rem 1rem; }

@media (hover: hover) {
  .btn-primary:hover { background: var(--accent-press); border-color: var(--accent-press); }
  .btn-secondary:hover { background: var(--chip); }
  .text-link:hover, .card-link:hover, .site-header nav a:hover { text-decoration-thickness: 2px; }
}
.btn-primary:active { background: var(--accent-press); border-color: var(--accent-press); transition-duration: 60ms; }
.btn-secondary:active { background: var(--chip); transition-duration: 60ms; }

.text-link, .card-link {
  font-weight: 700;
  color: var(--accent);
  text-decoration: underline;
  text-decoration-thickness: 1px;
}

/* ---------- Header ---------- */

.header-inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 1.5rem;
  padding-block: 1rem;
}
.wordmark {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font: 800 1.375rem/1 var(--display);
  text-decoration: none;
  min-height: 2.75rem;
}
/* The route node, reused as the logo mark */
.wordmark-node {
  width: 0.75rem; height: 0.75rem;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 1rem 0 0 -0.2rem var(--accent);
  margin-right: 0.8rem;
}
.site-header nav { margin-left: auto; }
.site-header nav ul { display: flex; gap: 0.25rem 1.25rem; flex-wrap: wrap; }
.site-header nav a {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  text-decoration: none;
  font-weight: 700;
}

@media (max-width: 34rem) {
  /* Nav wraps to its own row instead of disappearing */
  .site-header nav { order: 3; margin-left: 0; width: 100%; }
  .header-inner > .btn { margin-left: auto; }
}

