.hero { padding-block: clamp(2.5rem, 6vw, 6rem) clamp(4rem, 8vw, 7rem); }
.hero-inner {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr);
  gap: clamp(2.5rem, 5vw, 4.5rem);
  align-items: center;
}
.hero h1 {
  font-size: clamp(2.25rem, 1.3rem + 3.6vw, 4.25rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.02;
}
.lede {
  margin-top: 1.5rem;
  font-size: 1.1875rem;
  color: var(--muted);
  max-width: 34rem;
}
.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem 1.75rem;
  margin-top: 2.25rem;
}
.hero-actions .text-link { min-height: 2.75rem; display: inline-flex; align-items: center; }
.fine { margin-top: 1rem; font-size: 0.9375rem; color: var(--muted); }

