}
.route-from { display: grid; min-width: 0; overflow-wrap: anywhere; }
.route-subject { font-weight: 700; }
.route-meta { font-size: 0.875rem; color: var(--muted); }
.route-line {
  position: relative;
  height: 2px;
  background: var(--line);
  transform-origin: left center;
}
.route-line::before,
.route-line::after {
  content: "";
  position: absolute;
  top: 50%;
  border-radius: 50%;
  translate: 0 -50%;
}
.route-line::before { left: -3px; width: 7px; height: 7px; background: var(--line); }
.route-line::after { right: -5px; width: 10px; height: 10px; background: var(--accent); }
.route-line-dashed {
  background: repeating-linear-gradient(90deg, var(--line) 0 4px, transparent 4px 8px);
}
.route-line-dashed::after { background: var(--surface); border: 2px solid var(--accent); }

.route-to {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.3rem 0.75rem 0.3rem 0.3rem;
  border-radius: var(--r-chip);
  background: var(--chip);
  font-weight: 700;
  font-size: 0.9375rem;
  white-space: nowrap;
}
.avatar {
  display: grid;
  place-items: center;
  width: 1.75rem; height: 1.75rem;
  border-radius: 50%;
  background: var(--accent);
  color: var(--surface);
  font-size: 0.75rem;
  letter-spacing: 0.02em;
}

.route-mini { font-size: 0.875rem; }
.route-mini .route-from { color: var(--muted); font-weight: 700; }
.route-mini .route-to { padding: 0.2rem 0.65rem; font-size: 0.875rem; white-space: normal; }

