  /* Hero rows: destination drops under the subject so nothing squeezes */
  .routes .route { grid-template-columns: minmax(1.5rem, 2.5rem) auto; row-gap: 0.5rem; }
  .routes .route-from { grid-column: 1 / -1; }
  .routes .route-to { justify-self: start; }
}

