  .routes .route-to { animation: arrive 300ms var(--ease) backwards; }
  .routes .route:nth-child(1) .route-line { animation-delay: 250ms; }
  .routes .route:nth-child(1) .route-to { animation-delay: 750ms; }
  .routes .route:nth-child(2) .route-line { animation-delay: 450ms; }
  .routes .route:nth-child(2) .route-to { animation-delay: 950ms; }
  .routes .route:nth-child(3) .route-line { animation-delay: 650ms; }
  .routes .route:nth-child(3) .route-to { animation-delay: 1150ms; }
}
@keyframes draw { from { transform: scaleX(0); } }
@keyframes arrive { from { opacity: 0; transform: translateX(-0.5rem); } }

