.tier-featured { border: 2px solid var(--accent); padding: calc(1.75rem - 1px); }
.tier-top { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 0.5rem; }
.tier h3 { font-size: 1.5rem; font-weight: 700; }
.price { display: flex; align-items: baseline; gap: 0.375rem; }
.amount {
  font: 800 2.75rem/1 var(--display);
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
}
.per { color: var(--muted); }
.tier-list { display: grid; gap: 0.625rem; }
.tier-list li { padding-left: 1.5rem; position: relative; }
.tier-list li::before {
  content: "";
  position: absolute;
  left: 0.2rem; top: 0.6em;
  width: 0.5rem; height: 0.5rem;
  border-radius: 50%;
  background: var(--accent);
}
.tier .btn { margin-top: auto; }

/* ---------- Footer ---------- */

.site-footer {
  background: var(--ink);
  color: var(--surface);
  padding-block: 3.5rem 2rem;
  line-height: 1.7;
  --ring: var(--foot-muted);
}
.site-footer .wordmark-node { background: var(--surface); box-shadow: 1rem 0 0 -0.2rem var(--surface); }
.footer-inner {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 2fr);
  gap: 2.5rem 3rem;
}
.footer-brand p { color: var(--foot-muted); margin-top: 0.5rem; }
.footer-nav {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(8.5rem, 1fr));
  gap: 2rem;
}
.footer-nav h2 { font: 700 1rem/1.3 var(--body); margin-bottom: 0.5rem; }
.footer-nav a {
  display: inline-block;
  padding-block: 0.2rem;
  color: var(--foot-muted);
  text-decoration: none;
}
@media (hover: hover) { .footer-nav a:hover { color: var(--surface); text-decoration: underline; } }
.copyright {
  grid-column: 1 / -1;
  padding-top: 1.5rem;
  border-top: 1px solid oklch(0.40 0.03 200);
  color: var(--foot-muted);
  font-size: 0.9375rem;
}

@media (max-width: 48rem) {
  .footer-inner { grid-template-columns: minmax(0, 1fr); }
}

